<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#7EE787;">    type</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;">safetensors</span></span>
